'use client';
import { useReportWebVitals } from 'next/web-vitals';

export function WebVitalsReporter() {
  // This hook automatically calculates the exact Google Web Vitals metrics
  // as real users interact with the site!
  useReportWebVitals((metric) => {

    // You can send these metrics to Google Analytics, Vercel Analytics, etc.
    if (metric.name === 'LCP') {
      console.log(`Largest Contentful Paint took ${metric.value} milliseconds`);

      // Example: Send to custom analytics endpoint
      fetch('/api/analytics', { body: JSON.stringify(metric), method: 'POST' });
    }
  });

  return null;
}
